下面的实现不保留归档权限，先统一验证名称与条目类型，再流式计数写入 staging。最终目录应由单个任务独占，调用方不要并发创建同一路径。

```python
from __future__ import annotations

import os
import stat
import tempfile
import unicodedata
import zipfile
from pathlib import Path, PurePosixPath


_WINDOWS_RESERVED = {
    "CON", "PRN", "AUX", "NUL",
    *(f"COM{i}" for i in range(1, 10)),
    *(f"LPT{i}" for i in range(1, 10)),
}


def _safe_zip_parts(name: str) -> tuple[str, ...]:
    if "\x00" in name:
        raise ValueError("ZIP entry contains NUL")
    path = PurePosixPath(name.replace("\\", "/"))
    if path.is_absolute() or path == PurePosixPath("."):
        raise ValueError(f"unsafe ZIP path: {name!r}")

    parts = path.parts
    for part in parts:
        if part in {"", ".", ".."} or ":" in part:
            raise ValueError(f"unsafe ZIP path: {name!r}")
        if part.rstrip(" .") != part:
            raise ValueError(f"unsafe Windows ZIP name: {name!r}")
        if part.split(".", 1)[0].upper() in _WINDOWS_RESERVED:
            raise ValueError(f"reserved Windows ZIP name: {name!r}")
    return parts


def safe_extract_zip(
    archive_path: str | Path,
    destination: str | Path,
    *,
    max_entries: int = 1000,
    max_file_size: int = 64 * 1024 * 1024,
    max_total_size: int = 256 * 1024 * 1024,
) -> None:
    if min(max_entries, max_file_size, max_total_size) <= 0:
        raise ValueError("extraction limits must be positive")

    destination = Path(destination)
    if destination.exists():
        raise FileExistsError(f"destination already exists: {destination}")
    destination.parent.mkdir(parents=True, exist_ok=True)

    plans: list[tuple[zipfile.ZipInfo, tuple[str, ...], bool]] = []
    nodes: dict[tuple[str, ...], str] = {}
    declared_total = 0

    with zipfile.ZipFile(archive_path) as archive:
        infos = archive.infolist()
        if len(infos) > max_entries:
            raise ValueError("ZIP contains too many entries")

        for info in infos:
            if info.flag_bits & 1:
                raise ValueError("encrypted ZIP entries are not accepted")
            parts = _safe_zip_parts(info.filename)
            mode = info.external_attr >> 16
            file_type = stat.S_IFMT(mode)
            if file_type not in {0, stat.S_IFREG, stat.S_IFDIR}:
                raise ValueError(f"special ZIP entry is not accepted: {info.filename!r}")

            is_directory = info.is_dir()
            key = tuple(unicodedata.normalize("NFC", p).casefold() for p in parts)
            for end in range(1, len(key)):
                prefix = key[:end]
                if nodes.get(prefix) == "file":
                    raise ValueError("ZIP file/directory path conflict")
                nodes.setdefault(prefix, "directory")

            existing = nodes.get(key)
            if is_directory:
                if existing == "file":
                    raise ValueError("ZIP file/directory path conflict")
                nodes[key] = "directory"
            else:
                if existing is not None:
                    raise ValueError("duplicate ZIP output path")
                nodes[key] = "file"
                if info.file_size > max_file_size:
                    raise ValueError("ZIP entry exceeds max_file_size")
                declared_total += info.file_size
                if declared_total > max_total_size:
                    raise ValueError("ZIP exceeds max_total_size")
            plans.append((info, parts, is_directory))

        with tempfile.TemporaryDirectory(
            dir=destination.parent, prefix=f".{destination.name}.staging."
        ) as raw_staging:
            staging = Path(raw_staging) / "payload"
            staging.mkdir()
            actual_total = 0

            for info, parts, is_directory in plans:
                output = staging.joinpath(*parts)
                if is_directory:
                    output.mkdir(parents=True, exist_ok=True)
                    continue

                output.parent.mkdir(parents=True, exist_ok=True)
                written = 0
                with archive.open(info) as source, output.open("xb") as target:
                    while chunk := source.read(64 * 1024):
                        written += len(chunk)
                        actual_total += len(chunk)
                        if written > max_file_size or actual_total > max_total_size:
                            raise ValueError("ZIP exceeded extraction limits")
                        target.write(chunk)
                if written != info.file_size:
                    raise ValueError("ZIP entry size does not match metadata")

            os.replace(staging, destination)
```

若还允许归档内再套归档，不要递归自动解压；每一层都必须重新经过同样的预算与校验。
